  /**
   * L2CrossDomainMessenger contract encode message, such as hashCrossDomainMessagev1
   *
   * @param options.sender    The sender of the cross domain message
   * @param options.target    The target of the cross domain message
   * @param options.value     The value being sent with the cross domain message
   * @param options.messageNonce     The cross domain message nonce
   * @param options.message      The message passed along with the cross domain message
   */
  public encodeFunctionMessage(options: {
    sender: string
    target: string
    value: BigNumber
    messageNonce: BigNumber
    message: string
  }) {
    const {
      sender,
      target,
      value,
      messageNonce,
      message,
    } = options;
    const encoded = this.l2CrossDomainMessenger.interface.encodeFunctionData(
      'relayMessage',
      [sender, target, value, messageNonce, message]
    )

    return keccak256(encoded)
  }

