  /**
   * Generates the proof required to finalize an L2 to L1 message.
   *
   * @param message Message to generate a proof for.
   * @returns Proof that can be used to finalize the message.
   */
  public async getWithdrawMessageProof(
    message: MessageLike
  ): Promise<WithdrawMessageProof> {
    const resolved = await this.toCrossChainMessage(message)
    Console.log('getWithdrawMessageProof resolved', resolved)
    if (resolved.direction === MessageDirection.L1_TO_L2) {
      throw new Error(`can only generate proofs for L2 to L1 messages`)
    }

    Console.log(
      'getWithdrawMessageProof this.contracts.l1.Rollup',
      this.contracts.l1.Rollup
    )

    // Rollup roll up check
    const latestL2BlockNum = await this.getFinalizedL2BlockNumber()
    Console.log('getWithdrawMessageProof latestL2BlockNum', latestL2BlockNum)
    Console.log(
      'getWithdrawMessageProof resolved.blockNumber',
      resolved.blockNumber
    )
    if (latestL2BlockNum < resolved.blockNumber) {
      throw new Error(`state root for message not yet published`)
    }

    const withdrawal = await this.toLowLevelMessage(resolved)

    Console.log('getWithdrawMessageProof withdrawal', withdrawal)
    // const versionNonce = decodeVersionedNonce(withdrawal.messageNonce)

    let withdrawalIndex
    let withdrawalProof
    let withdrawalRoot
    let withdrawalLeaf
    Console.log(
      'getWithdrawMessageProof backendURL',
      this.backendURL + '/getProof'
    )
    await axios
      .get(this.backendURL + '/getProof', {
        params: {
          nonce: withdrawal.messageNonce, // versionNonce.nonce,
        },
      })
      .then(async (response) => {
        // "0xf06d804b841b30d6d82a2d62ad26a79d0fc1b6c770f47815c721f64aff72bb17"
        withdrawalIndex = response.data.index
        withdrawalProof = response.data.proof
        withdrawalRoot = response.data.root
        withdrawalLeaf = response.data.leaf
        // const withdrawalHash2 = this.encodeFunctionMessage({
        //   ...withdrawal,
        //   message: withdrawal.encodedMessage,
        // })
        // const withdrawalHash3 = this.encodeFunctionMessage(withdrawal)

        if (withdrawalLeaf !== withdrawal.messageHash) {
          throw new Error(
            `can not get proof for ${resolved}, leaf not equal expect ${withdrawal.messageHash} got ${withdrawalLeaf}`
          )
        }
      })
      .catch((error) => {
        throw new Error(`can not get proof from ${this.backendURL}, ${error}`)
      })

    Console.log('getWithdrawMessageProof reault', {
      withdrawalIndex,
      withdrawalProof,
      withdrawalRoot,
      withdrawalLeaf,
    })
    return {
      withdrawalIndex,
      withdrawalProof,
      withdrawalRoot,
      withdrawalLeaf,
    }
  }

